public interface ProgramNotificationRepository extends JpaRepository<ProgramNotification,UUID>{Optional<ProgramNotification> findByIdAndTenantId(UUID id,UUID tenantId);Page<ProgramNotification> findAllByTenantIdAndRecipientEmployeeIdOrderByCreatedAtDesc(UUID tenantId,UUID employeeId,Pageable pageable);List<ProgramNotification> findAllByTenantIdAndProgramIdAndChannelAndStatusOrderByCreatedAtAsc(UUID tenantId,UUID programId,ProgramTypes.NotificationChannel channel,ProgramTypes.NotificationStatus status);List<ProgramNotification> findAllByTenantIdAndReminderDedupeKeyIn(UUID tenantId,Collection<String> keys);Page<ProgramNotification> findAllByTenantIdAndProgramIdAndReminderDedupeKeyIsNotNullOrderByCreatedAtDesc(UUID tenantId,UUID programId,Pageable pageable);@Modifying @Query("update ProgramNotification n set n.status=:claimed where n.id=:id and n.tenantId=:tenantId and n.status=:ready")int claimReady(@Param("tenantId")UUID tenantId,@Param("id")UUID id,@Param("ready")ProgramTypes.NotificationStatus ready,@Param("claimed")ProgramTypes.NotificationStatus claimed);}
